create table public.programme_access (user_id uuid not null references auth.users(id) on delete cascade, programme text not null check(programme in ('executive-leadership-readiness','presentation-speaking-skills')), status text not null default 'active' check(status in ('active','revoked')), granted_at timestamptz not null default now(), primary key(user_id,programme)); alter table public.programme_access enable row level security; revoke all on public.programme_access from anon,authenticated; grant select on public.programme_access to authenticated; grant all on public.programme_access to service_role; create policy programme_access_read_own on public.programme_access for select to authenticated using((select auth.uid())=user_id);
create table public.programme_invitations (id uuid primary key default gen_random_uuid(), email text not null, programme text not null check(programme in ('executive-leadership-readiness','presentation-speaking-skills')), code_hash text unique not null, expires_at timestamptz not null, used_at timestamptz, created_at timestamptz not null default now()); alter table public.programme_invitations enable row level security; revoke all on public.programme_invitations from anon,authenticated; grant all on public.programme_invitations to service_role; create policy invitations_service_only on public.programme_invitations for all to service_role using(true) with check(true);
insert into public.programme_access(user_id,programme) select distinct p.user_id,'executive-leadership-readiness' from public.profiles p join public.participant_programmes e on e.participant_id=p.id join public.programmes g on g.id=e.programme_id where p.user_id is not null and g.slug='executive-leadership-readiness' and e.status in ('active','completed') on conflict do nothing;
insert into public.programme_access(user_id,programme) select user_id,'presentation-speaking-skills' from public.speaking_enrolments on conflict do nothing;
create function public.redeem_programme_invitation(candidate_id uuid, selected_programme text, supplied_hash text) returns boolean language plpgsql security invoker set search_path=public,pg_temp as $$
declare invitation_id uuid; verified_email text;
begin
select lower(email) into verified_email from auth.users where id=candidate_id and email_confirmed_at is not null;
if verified_email is null then return false; end if;
update public.programme_invitations set used_at=now() where code_hash=supplied_hash and email=verified_email and programme=selected_programme and used_at is null and expires_at>now() returning id into invitation_id;
if invitation_id is null then return false; end if;
insert into public.programme_access(user_id,programme,status) values(candidate_id,selected_programme,'active') on conflict(user_id,programme) do update set status='active',granted_at=now();
return true; end; $$;
revoke all on function public.redeem_programme_invitation(uuid,text,text) from public,anon,authenticated; grant execute on function public.redeem_programme_invitation(uuid,text,text) to service_role;
